import{_ as t,c as o,o as i,ag as e}from"./chunks/framework.DPDPlp3K.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"shopify/storefronts/Email Direct Marketing.md","filePath":"shopify/storefronts/Email Direct Marketing.md"}'),r={name:"shopify/storefronts/Email Direct Marketing.md"};function s(p,a,n,l,h,c){return i(),o("div",null,a[0]||(a[0]=[e('<h2 id="标题备选" tabindex="-1">标题备选 <a class="header-anchor" href="#标题备选" aria-label="Permalink to &quot;标题备选&quot;">​</a></h2><ol><li>Shopify 开发实战：Shopify Email Direct Marketing 一篇讲清楚</li><li>手把手梳理 Shopify：Shopify Email Direct Marketing 的关键用法和避坑点</li><li>做 Shopify 项目别只会改主题，这篇带你搞懂 Shopify Email Direct Marketing</li></ol><h2 id="摘要" tabindex="-1">摘要 <a class="header-anchor" href="#摘要" aria-label="Permalink to &quot;摘要&quot;">​</a></h2><p>这篇文章适合 Shopify 主题和应用开发者，围绕「Shopify Email Direct Marketing」梳理核心概念、配置路径和实战注意点，方便项目中快速对照。</p><h2 id="正文" tabindex="-1">正文 <a class="header-anchor" href="#正文" aria-label="Permalink to &quot;正文&quot;">​</a></h2><p>哈喽大家好👋 我是程序🦍kk。把复杂知识掰成大白话讲明白，是我一直以来的小追求✨；<strong>打好基础才能稳步进阶</strong>，是我始终秉持的学习理念～</p><blockquote><p>📢 我搭建了5000人程序猿专属学习交流群 群内会同步前端开发/全栈开发/Web3开发/远程工作等干货资源 关注我并回复 <strong>加群</strong> ，就能加入交流圈啦🚀</p></blockquote><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p><strong>Shopify 项目最容易卡住的地方，往往不是“会不会写代码”，而是主题、应用和后台配置之间的关系没理顺。</strong></p><p>很多同学做 Shopify 开发时，会同时碰到 Liquid、主题目录、Checkout、Metafields、应用后台、性能优化这些概念。单独看不难，放到真实项目里就容易散。</p><p>这篇围绕「Shopify Email Direct Marketing」把原始笔记整理成更适合阅读和复用的版本，适合做主题开发、应用开发或者接手 Shopify 项目时快速对照。</p><h2 id="shopify-实战整理" tabindex="-1">Shopify 实战整理 <a class="header-anchor" href="#shopify-实战整理" aria-label="Permalink to &quot;Shopify 实战整理&quot;">​</a></h2><p>下面进入 Shopify 相关内容整理。建议大家边看边对照自己的店铺、主题代码和应用后台，很多问题只有放到真实配置里才容易看清楚。</p><p>如果你正在做 Shopify 项目，可以重点留意主题代码、后台配置、应用能力和官方限制之间的边界，很多线上问题都出在这些交界处。</p><p>Emarsys 是 SAP 旗下的一个 B2C 营销自动化平台（Marketing Automation Platform），主要面向电商、零售品牌。</p><p>核心功能</p><p>邮件营销：发送个性化营销邮件、促销邮件、触发式邮件（如购物车未结单提醒） 用户分群：根据用户属性、行为数据将用户划分到不同的 Contact List，进行精准触达 SMS 营销：短信推送 自动化工作流：设置触发条件，自动执行营销动作（如用户注册后自动发欢迎邮件） 数据分析：追踪邮件打开率、点击率、转化率等 在 EcoFlow 项目中的作用</p><p>EcoFlow 用 Emarsys 管理邮件订阅用户，代码中的这些概念都是 Emarsys 的术语：</p><p>代码字段 含义 contactListId Emarsys 中的用户分组列表 ID，比如&quot;美国促销用户组&quot; fields 用户属性字段，比如用户偏好品类、订阅来源渠道 fields[].type: &quot;single&quot; 单选属性，值是一个数字（对应 Emarsys 里配置的选项 ID） fields[].type: &quot;multiple&quot; 多选属性，值是数字数组 eventTracking 订阅事件的来源追踪，用于营销归因分析 subscribe_info Cookie Emarsys 写入的 Cookie，记录用户从哪个页面/活动进入 简单来说：每次用户在网站填写邮件订阅，EcoFlow 就调用 Emarsys 的 API，把这个用户加入对应的联系人列表，并打上各种属性标签（fields），后续 Emarsys 就能根据这些标签给用户发送定制化的营销邮件。</p><h2 id="写在最后" tabindex="-1">写在最后 <a class="header-anchor" href="#写在最后" aria-label="Permalink to &quot;写在最后&quot;">​</a></h2><p>好啦，今天的分享就到这里！</p><p>💬 互动时间：</p><p>你现在做 Shopify 更常遇到的是主题开发、Checkout 定制、应用接入，还是性能优化？如果你在「Shopify Email Direct Marketing」上踩过坑，也可以把场景留言出来。</p><p>最后，感谢你看到这里👏</p><p>如果喜欢这篇内容，不妨顺手给小编安排一波👇 <strong>点赞</strong>👍｜<strong>转发</strong>📲｜<strong>推荐</strong>❤️｜<strong>评论</strong>📣</p><p>要是想第一时间蹲到新内容推送，记得给我点个<strong>星标</strong>⭐️</p><p>更多干货内容正在持续填坑中，咱们下期见👋</p><h2 id="标签建议" tabindex="-1">标签建议 <a class="header-anchor" href="#标签建议" aria-label="Permalink to &quot;标签建议&quot;">​</a></h2><p>Shopify、主题开发、独立站</p>',29)]))}const m=t(r,[["render",s]]);export{d as __pageData,m as default};
